import { useMemo, useState, type FormEvent } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { db } from '@lork/sdk'
import { BRANDS, PARTS, VEHICLES, formatPrice, generationsFor, modelsForBrand } from '@/data/catalog'
import ConsentCheckbox from '@/components/ConsentCheckbox'

const advantages = [
  {
    title: 'Собственное производство',
    text: 'Изготавливаем пороги и арки на своём оборудовании: контролируем геометрию детали, толщину металла и качество кромок на каждом этапе.',
  },
  {
    title: 'Новые детали, не б/у',
    text: 'В каталоге только новые ремонтные детали — их можно резать и варить без сюрпризов от прошлой эксплуатации.',
  },
  {
    title: 'Подгонка под кузов',
    text: 'Детали делаются по образцу штатных элементов кузова, поэтому при ремонте меньше подгонки и риска перекоса.',
  },
  {
    title: 'Покупка напрямую',
    text: 'Покупаете у производителя и сразу видите итоговую цену в карточке при выборе материала и комплектации.',
  },
]

const process = [
  { step: '01', title: 'Выбор автомобиля', text: 'Укажите марку, модель и поколение — покажем подходящие детали.' },
  { step: '02', title: 'Материал и комплектация', text: 'В карточке выберите материал и набор — цена обновится сразу.' },
  { step: '03', title: 'Корзина и оформление', text: 'Соберите состав заказа и оставьте имя, телефон, город и комментарий.' },
  { step: '04', title: 'Подтверждение', text: 'Мы свяжемся с вами, чтобы подтвердить состав заказа и детали доставки.' },
]

export default function Home() {
  const featured = PARTS.slice(0, 4)
  const navigate = useNavigate()

  const [brand, setBrand] = useState('')
  const [model, setModel] = useState('')
  const [generation, setGeneration] = useState('')

  const [callOpen, setCallOpen] = useState(false)
  const [callName, setCallName] = useState('')
  const [callPhone, setCallPhone] = useState('')
  const [callError, setCallError] = useState('')
  const [callSending, setCallSending] = useState(false)
  const [callSent, setCallSent] = useState(false)
  const [callConsent, setCallConsent] = useState(false)

  const models = useMemo(() => (brand ? modelsForBrand(brand) : []), [brand])
  const generations = useMemo(
    () => (brand && model ? generationsFor(brand, model) : []),
    [brand, model],
  )
  const ready = Boolean(brand && model && generation)

  const handleBrand = (value: string) => {
    setBrand(value)
    setModel('')
    setGeneration('')
  }

  const handleModel = (value: string) => {
    setModel(value)
    setGeneration('')
  }

  const pickVehicle = () => {
    if (!ready) return
    const params = new URLSearchParams({ brand, model, generation })
    navigate(`/catalog?${params.toString()}`)
  }

  const openCall = () => {
    setCallOpen(true)
    setCallError('')
    setCallSent(false)
    setCallConsent(false)
  }

  const closeCall = () => {
    setCallOpen(false)
    setCallError('')
    setCallConsent(false)
  }

  const handleCallPhone = (value: string) => {
    const digits = value.replace(/\D/g, '').replace(/^7/, '').slice(0, 10)
    setCallPhone(digits)
  }

  const submitCall = async (event: FormEvent) => {
    event.preventDefault()
    if (callSending) return
    const name = callName.trim()
    if (name.length < 2) {
      setCallError('Укажите имя — минимум 2 символа.')
      return
    }
    if (callPhone.length !== 10) {
      setCallError('Введите номер телефона полностью: +7 и 10 цифр.')
      return
    }
    if (!callConsent) {
      setCallError('Отметьте согласие на обработку персональных данных.')
      return
    }
    const phone = `+7${callPhone}`
    setCallError('')
    setCallSending(true)
    try {
      const { error } = await db.from('orders_public').insert({
        order_number: 'CALLBACK',
        customer_name: name,
        phone,
        city: '—',
        comment: 'Обратный звонок с главной страницы «Довериться профессионалу».',
        items: [],
        total: 0,
        status: 'callback',
        consent_pdn: true,
      })
      if (error) throw error
      setCallSent(true)
      setCallName('')
      setCallPhone('')
      setCallConsent(false)
    } catch {
      setCallError('Не удалось отправить заявку. Попробуйте ещё раз.')
    } finally {
      setCallSending(false)
    }
  }

  return (
    <div>
      <section className="border-b border-border bg-card">
        <div className="mx-auto grid w-full max-w-6xl gap-10 px-4 py-14 sm:px-6 lg:grid-cols-2 lg:items-center lg:py-20">
          <div>
            <span className="inline-flex items-center rounded-full border border-border bg-secondary px-3 py-1 text-xs font-medium uppercase tracking-wide text-muted-foreground">
              Собственное производство
            </span>
            <h1 className="mt-4 text-3xl font-bold leading-tight tracking-tight sm:text-4xl lg:text-5xl">
              Ремонтные пороги и колёсные арки для вашего автомобиля
            </h1>
            <p className="mt-4 max-w-xl text-base leading-relaxed text-muted-foreground">
              Новые детали для кузовного ремонта: подберём по марке, модели и поколению, поможем
              выбрать материал и комплектацию и соберём заказ.
            </p>
            <div className="mt-6 flex flex-wrap items-center gap-3">
              <Link
                to="/catalog"
                className="rounded-md bg-primary px-5 py-3 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90"
              >
                Подобрать самостоятельно
              </Link>
              <button
                type="button"
                onClick={openCall}
                className="rounded-md border border-[#7dd3fc] bg-[#e0f2fe] px-5 py-3 text-sm font-medium text-[#0369a1] transition-colors hover:border-[#38bdf8] hover:bg-[#bae6fd]"
              >
                Довериться профессионалу
              </button>
            </div>
            <div className="mt-6 flex flex-wrap gap-x-6 gap-y-2 text-sm text-muted-foreground">
              <span>{VEHICLES.length} моделей в подборе</span>
              <span>{PARTS.length} деталей в каталоге</span>
              <span>{BRANDS.length} марок</span>
            </div>
          </div>

          <div className="relative overflow-hidden">
            <img
              src="data:image/jpeg;base64,"
              alt="Работа с кузовными деталями автомобиля"
              className="h-72 w-full sm:h-96 object-contain"
              loading="eager"
            />
            <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-foreground/80 to-transparent p-5">
              <div className="text-sm font-medium text-[#f8fafc]">
                Пороги и арки из новых материалов — для сварного кузовного ремонта
              </div>
            </div>
          </div>
        </div>
      </section>

      <section className="mx-auto w-full max-w-6xl px-4 pt-14 sm:px-6 bg-[#e0f2fe] border-[#7dd3fc]">
        <div className="max-w-2xl">
          <h2 className="text-2xl font-bold tracking-tight sm:text-3xl">Подбор по автомобилю</h2>
          <p className="mt-3 text-muted-foreground">
            Укажите марку, модель и поколение — перейдём в каталог с выбранным автомобилем.
          </p>
        </div>

        <section className="mt-6 rounded-xl border border-border bg-card p-4 sm:p-5">
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
            <label className="block">
              <span className="mb-1.5 block text-sm font-bold text-[#16a34a]">Марка</span>
              <select
                value={brand}
                onChange={(event) => handleBrand(event.target.value)}
                className="h-11 w-full rounded-md border border-input bg-background px-3 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <option value="">Все марки</option>
                {BRANDS.map((item) => (
                  <option key={item} value={item}>
                    {item}
                  </option>
                ))}
              </select>
            </label>

            <label className="block">
              <span className="mb-1.5 block text-sm font-bold text-[#16a34a]">Модель</span>
              <select
                value={model}
                onChange={(event) => handleModel(event.target.value)}
                disabled={!brand}
                className="h-11 w-full rounded-md border border-input bg-background px-3 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-60"
              >
                <option value="">{brand ? 'Все модели' : 'Сначала выберите марку'}</option>
                {models.map((item) => (
                  <option key={item} value={item}>
                    {item}
                  </option>
                ))}
              </select>
            </label>

            <label className="block">
              <span className="mb-1.5 block text-sm font-bold text-[#16a34a]">Поколение</span>
              <select
                value={generation}
                onChange={(event) => setGeneration(event.target.value)}
                disabled={!model}
                className="h-11 w-full rounded-md border border-input bg-background px-3 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-60"
              >
                <option value="">{model ? 'Все поколения' : 'Сначала выберите модель'}</option>
                {generations.map((item) => (
                  <option key={item} value={item}>
                    {item}
                  </option>
                ))}
              </select>
            </label>

            <div className="flex items-end">
              <button
                type="button"
                onClick={pickVehicle}
                disabled={!ready}
                className="h-11 w-full rounded-md bg-primary px-5 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90 disabled:pointer-events-none disabled:opacity-50"
              >
                Подобрать
              </button>
            </div>
          </div>
        </section>
      </section>

      <section className="mx-auto w-full max-w-6xl px-4 py-14 sm:px-6">
        <div className="max-w-2xl">
          <h2 className="text-2xl font-bold tracking-tight sm:text-3xl">
            Почему покупают у производителя
          </h2>
          <p className="mt-3 text-muted-foreground">
            Мы сами производим ремонтные детали, поэтому отвечаем за геометрию, материал и качество
            каждой партии.
          </p>
        </div>

        <div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {advantages.map((item) => (
            <article
              key={item.title}
              className="rounded-xl border border-border bg-card p-5 transition-colors hover:border-accent"
            >
              <div className="flex h-9 w-9 items-center justify-center rounded-md bg-primary text-primary-foreground">
                <svg
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  className="h-5 w-5"
                  aria-hidden="true"
                >
                  <path d="M20 6 9 17l-5-5" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              </div>
              <h3 className="mt-4 font-semibold">{item.title}</h3>
              <p className="mt-2 text-sm leading-relaxed text-muted-foreground">{item.text}</p>
            </article>
          ))}
        </div>
      </section>

      <section className="border-y border-border bg-surface">
        <div className="mx-auto w-full max-w-6xl px-4 py-14 sm:px-6">
          <h2 className="text-2xl font-bold tracking-tight sm:text-3xl">Как проходит покупка</h2>
          <div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {process.map((item) => (
              <div key={item.step} className="rounded-xl border border-border bg-card p-5">
                <div className="text-sm font-bold text-accent">{item.step}</div>
                <h3 className="mt-2 font-semibold">{item.title}</h3>
                <p className="mt-2 text-sm leading-relaxed text-muted-foreground">{item.text}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section className="mx-auto w-full max-w-6xl px-4 py-14 sm:px-6">
        <div className="flex flex-wrap items-end justify-between gap-4">
          <div>
            <h2 className="text-2xl font-bold tracking-tight sm:text-3xl">Популярные детали</h2>
            <p className="mt-2 text-muted-foreground">
              Выберите автомобиль в каталоге, чтобы увидеть все варианты.
            </p>
          </div>
          <Link
            to="/catalog"
            className="rounded-md border border-border bg-card px-4 py-2 text-sm font-medium transition-colors hover:border-accent hover:text-accent"
          >
            Весь каталог
          </Link>
        </div>

        <div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {featured.map((part) => (
            <Link
              key={part.id}
              to={`/product/${part.id}`}
              className="group overflow-hidden rounded-xl border border-border bg-card transition-colors hover:border-accent"
            >
              <div className="aspect-[4/3] overflow-hidden bg-surface">
                <img
                  src={part.images[0]}
                  alt={part.title}
                  className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-105"
                  loading="lazy"
                />
              </div>
              <div className="p-4">
                <div className="text-xs uppercase tracking-wide text-muted-foreground">
                  {part.type} · {part.vehicle.brand} {part.vehicle.model}
                </div>
                <h3 className="mt-1 font-semibold leading-snug">{part.title}</h3>
                <div className="mt-3 flex items-center justify-between">
                  <span className="font-bold text-accent">
                    от {formatPrice(part.type === 'арка' ? 1950 : 1790)}
                  </span>
                  <span className="text-xs text-muted-foreground">{part.side}</span>
                </div>
              </div>
            </Link>
          ))}
        </div>
      </section>

      <section className="mx-auto w-full max-w-6xl px-4 pb-16 sm:px-6">
        <div className="rounded-xl border border-border bg-foreground p-6 text-background sm:p-10">
          <div className="max-w-2xl">
            <h2 className="text-2xl font-bold tracking-tight">Подберите деталь под свой кузов</h2>
            <p className="mt-3 text-sm leading-relaxed text-background/75">
              В каталоге выберите марку, модель и поколение автомобиля — фильтр покажет пороги и
              арки, подходящие именно для вашего кузова.
            </p>
          </div>
          <Link
            to="/catalog"
            className="mt-6 inline-flex rounded-md bg-accent px-5 py-3 text-sm font-medium text-accent-foreground transition-colors hover:bg-accent/90"
          >
            Открыть каталог
          </Link>
        </div>
      </section>

      {callOpen && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-foreground/60 p-4"
          role="dialog"
          aria-modal="true"
          aria-labelledby="callback-title"
          onClick={closeCall}
        >
          <div
            className="w-full max-w-md rounded-xl border border-border bg-card p-6 shadow-xl"
            onClick={(event) => event.stopPropagation()}
          >
            {callSent ? (
              <div>
                <h2 id="callback-title" className="text-xl font-bold tracking-tight">
                  Заявка отправлена
                </h2>
                <p className="mt-3 text-sm leading-relaxed text-muted-foreground">
                  Быстро перезвоним и поможем.
                </p>
                <button
                  type="button"
                  onClick={closeCall}
                  className="mt-6 w-full rounded-md bg-primary px-5 py-3 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90"
                >
                  Закрыть
                </button>
              </div>
            ) : (
              <form onSubmit={submitCall} noValidate>
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <h2 id="callback-title" className="text-xl font-bold tracking-tight">
                      Быстро перезвоним и поможем
                    </h2>
                    <p className="mt-2 text-sm text-muted-foreground">
                      Оставьте имя и номер телефона — свяжемся с вами.
                    </p>
                  </div>
                  <button
                    type="button"
                    onClick={closeCall}
                    aria-label="Закрыть форму"
                    className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-md border border-border px-2 text-sm text-muted-foreground transition-colors hover:border-accent hover:text-accent"
                  >
                    ✕
                  </button>
                </div>

                <label className="mt-5 block">
                  <span className="mb-1.5 block text-sm font-medium">Ваше имя</span>
                  <input
                    type="text"
                    value={callName}
                    onChange={(event) => setCallName(event.target.value)}
                    placeholder="Как к вам обращаться"
                    className="h-11 w-full rounded-md border border-input bg-background px-3 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  />
                </label>

                <label className="mt-4 block">
                  <span className="mb-1.5 block text-sm font-medium">Номер телефона</span>
                  <div className="flex h-11 w-full overflow-hidden rounded-md border border-input bg-background focus-within:ring-2 focus-within:ring-ring">
                    <span className="flex items-center border-r border-input bg-secondary px-3 text-sm font-medium text-muted-foreground">
                      +7
                    </span>
                    <input
                      type="tel"
                      inputMode="tel"
                      value={callPhone
                        .replace(/(\d{3})(?=\d)/g, '$1 ')
                        .replace(/(\d{3}) (\d{3})(?=\d)/g, '$1 $2 ')}
                      onChange={(event) => handleCallPhone(event.target.value)}
                      placeholder="(999) 123-45-67"
                      aria-label="Номер телефона, начинается с +7"
                      className="h-full w-full bg-transparent px-3 text-sm outline-none"
                    />
                  </div>
                </label>

                {callError && (
                  <p className="mt-3 text-sm text-destructive" role="alert">
                    {callError}
                  </p>
                )}

                <ConsentCheckbox
                  id="call-consent"
                  checked={callConsent}
                  onChange={(checked) => {
                    setCallConsent(checked)
                    if (checked) setCallError((current) =>
                      current === 'Отметьте согласие на обработку персональных данных.'
                        ? ''
                        : current,
                    )
                  }}
                />

                <button
                  type="submit"
                  disabled={callSending}
                  className="mt-5 w-full rounded-md bg-primary px-5 py-3 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90 disabled:pointer-events-none disabled:opacity-60"
                >
                  {callSending ? 'Отправляем…' : 'Отправить заявку'}
                </button>
              </form>
            )}
          </div>
        </div>
      )}
    </div>
  )
}
